        ((issue && issue.assignees) || []).some(function (a) {
            return a && logins.indexOf(a.login) !== -1;
        }) || !!(issue && issue.assignee && issue.assignee.login !== undefined &&
                 logins.indexOf(issue.assignee.login) !== -1));
