    if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
        return null;
    }
    var rates = Object.create(null);
    var n = 0;
    Object.keys(parsed).forEach(function (k) {
        if (k === 'default') return;
        var e = parsePricingEntry(parsed[k]);
        if (e) { rates[k] = e; n += 1; }
    });
