        (backlog[bucket] || []).forEach(function (c) {
            if (!c || c.issue == null) return;
            ix.issue[c.issue] = c;             // backlog card wins: it owns
            ix.issueState[c.issue] = bucket;   // the issue-state history
        });
    });
    return ix;
