    var card = {
        issue: it.number,
        title: it.title,
        author: it.user && it.user.login,
        assignee: firstAssignee(it),
        labels: (it.labels || []).map(function (l) {
            return l && l.name || l;
        }),
        url: it.html_url,
        history: issueHistory[it.number] || []
    };
