        (result.reason ? ' (' + result.reason + ')' : '') +
        (result.key ? ' — ' + result.key + ' ' + result.leg : '') +
        (result.attempts ? ' after ' + result.attempts + ' attempt(s)' : ''));
    return result;
}

if (typeof module !== 'undefined' && module.exports) {
    module.exports = {
        action: action,
        resolveParams: resolveParams,
        envValue: envValue
    };
}

