            lower.indexOf('timed out') !== -1 ||
            lower.indexOf('command timeout') !== -1 ||
            lower.indexOf('timeout guard') !== -1) {
            timeoutCount += 1;
        }

        var request = parseRequestsLine(lines[i]);
        if (request) {
