}

/**
 * The printf row: field order is the contract
 * {"leg","at","prompt","completion","total","cacheRead","model"}.
 */
function buildRow(o) {
    o = o || {};
    var prompt = ledgerInt(o.prompt) || 0;
    var completion = ledgerInt(o.completion) || 0;
    return {
        leg: String(o.leg || ''),
        at: String(o.at || ''),
        prompt: prompt,
