/** `date -u +%Y-%m-%dT%H:%M:%SZ` — UTC ISO-8601, seconds precision. */
function utcStampZ(d) {
    var date = (d instanceof Date) ? d : new Date(d);
    if (isNaN(date.getTime())) return '';
    return date.toISOString().replace(/\.\d{3}Z$/, 'Z');
}

