    var reporter = loadReporter();
    var summary = reporter.buildSummary([{
        createdAt: '2026-06-01T00:00:00Z',
        startedAt: '2026-06-01T00:00:00Z',
        updatedAt: '2026-06-01T00:27:02Z',
