        feedbackLoopCount: 0,
        rateLimitRetryCount: 0,
        rateLimitDetected: false,
        timeoutCount: 0,
        durationSeconds: 60
    }], 1);
    var malicious = "';alert(1);//<script>alert(2)</script>" + '\u2028' + '\u2029';
    var html = reporter.buildHtml([{
        createdAt: '2026-06-01T00:00:00Z',
        agent: malicious,
        ticketKey: malicious,
        conclusion: 'success',
        samples: 1,
        resumeDetected: false,
