/**
 * gh-1108 — run title → token-row anchor. ONE vocabulary with the dedup
 * module: issue anchor via issueOfRunName ('#<n>' stub / 'gh-<n>' factory
 * families), PR anchor via a whole-token 'pr-<n>' scan (the stub's
 * '· pr-<N>' slot, gh-1075), leg via legOfRunName. pr wins — the finer
 * anchor when a title carries both ('teammate: workflow_dispatch #1040 ·
 * pr-1123 review' keys the ROW under pr-1123; issue-1040 has its own
 * dev-leg rows). Returns { key, leg, issue, pr } — key null when NEITHER
 * anchor resolves (unresolvable runs yield no row, never a wrong key).
 */
function parseRunAnchor(title) {
   var t = String(title || '');
   var pr = null;
   // whole-token pr-<n>: [^0-9a-zA-Z]pr-<n> not followed by a digit (the
   // anchoredNumberOf discipline: '#104' must not match '#1040'; same
   // guard for 'pr-11' vs 'pr-112').
   var re = /(?:^|[^0-9a-zA-Z])pr-(\d+)/g;
   var m = re.exec(t);
   while (m) {
       var after = t.charAt(m.index + m[0].length);
       if (after === '' || after < '0' || after > '9') { pr = parseInt(m[1], 10); break; }
       m = re.exec(t);
   }
   var issue = dedup.issueOfRunName(t);
   var leg = dedup.legOfRunName(t);
   return {
       pr: pr,
       issue: issue,
       leg: leg || '',
       key: pr != null ? 'pr-' + pr : (issue != null ? 'issue-' + issue : null)
   };
}
