function getCachedRunState(cache, runId, useCache) {
    if (!useCache) return null;
    var cached = cache.entries[runId];
    if (!cached) return null;
    if (cached.row) return { kind: 'row', row: cached.row, attemptRows: cached.attemptRows || [] };
