/**
 * gh-1108 — run title → token-row anchor. ONE title vocabulary with
 * teammateEventDedup: the issue anchor via issueOfRunName (stub '#<n>' and
 * factory 'gh-<n>' families), the leg via legOfRunName (stub tail /
 * '▶ leg (SM)' / emoji families), plus a whole-token 'pr-<n>' scan for the
 * PR-anchored dispatch slot (the stub's '· pr-<N>', gh-1075). pr wins over
 * issue — the finer anchor when a title carries both. Returns
 * { key, pr, issue, leg }; key is null when NEITHER anchor resolves — an
 * unresolvable run yields no row, never a wrong key.
 */
function parseRunAnchor(title) {
   var text = String(title || '');
   var pr = null;
   var re = /(?:^|[^0-9a-zA-Z])pr-(\d+)/g;
   var m = re.exec(text);
   while (m) {
       var after = text.charAt(m.index + m[0].length);
       if (after === '' || after < '0' || after > '9') { pr = parseInt(m[1], 10); break; }
       m = re.exec(text);
   }
   var issue = teammateEventDedup.issueOfRunName(text);
   var leg = teammateEventDedup.legOfRunName(text);
   return {
       pr: pr,
       issue: issue,
       leg: leg || '',
       key: pr != null ? 'pr-' + pr : (issue != null ? 'issue-' + issue : null)
   };
}
