```js
/**
 * gh-1108 — the keyed tokens projection: reporter rows → the map form the
 * tick consumes (tokensMapOf: 'pr-N'/'issue-N' → rows). One row per RUN
 * (the run's summed usage) in the printf row contract {leg, at, prompt,
 * completion, total, cacheRead, model}: prompt = read, completion = write,
 * total = prompt + completion, cacheRead = cached. The logs carry no model
 * id yet — model stays '' (normTokenRow → null downstream; pricing skips
 * it, tokens still render). Rows without a resolvable anchor drop (never a
 * wrong key). Retention mirrors the fa producer (js/factory/token_usage.js):
 * rows older than windowDays (default 14) drop, the newest keepPerKey
 * (default ROW_KEEP = 40) survive per key, sorted by at ascending.
 * Numbers only — no log text, no URLs (the snapshot's privacy invariant).
 */
function buildTokensMap(rows, opts) {
   opts = opts || {};
   var windowDays = (opts.windowDays == null || opts.windowDays === '') ?
       tokenUsage.DEFAULT_WINDOW_DAYS : parseInt(opts.windowDays, 10);
   var keepPerKey = (opts.keepPerKey == null || opts.keepPerKey === '') ?
       tokenUsage.ROW_KEEP : parseInt(opts.keepPerKey, 10);
   var cutoff = tokenUsage.cutoffIso(opts.now ? new Date(opts.now) : new Date(), windowDays);
   var byKey = {};
   (Array.isArray(rows) ? rows : []).forEach(function (row) {
       if (!row) return;
       var anchor = parseRunAnchor(row.title);
       if (!anchor.key) return;
       var prompt = +row.readTokens || 0;
       var completion = +row.writeTokens || 0;
       (byKey[anchor.key] = byKey[anchor.key] || []).push({
           leg: anchor.leg || legFromAgent(row.agent),
           at: String(row.createdAt || ''),
           prompt: prompt,
           completion: completion,
           total: prompt + completion,
           cacheRead: +row.cachedTokens || 0,
           model: ''
       });
   });
   var map = {};
   Object.keys(byKey).forEach(function (key) {
       var kept = byKey[key]
           .filter(function (r) { return String(r.at || '') >= cutoff; })
           .sort(function (a, b) { return String(a.at).localeCompare(String(b.at)); });
       kept = kept.length > keepPerKey ? kept.slice(kept.length - keepPerKey) : kept;
       if (kept.length) map[key] = kept;
   });
   return map;
}
``

