var EMOJI_LEG_MARKERS = [['🔧', 'rework'], ['🔍', 'review'], ['⚒️', 'dev']];

function emojiLegOf(name) {
    for (var i = 0; i < EMOJI_LEG_MARKERS.length; i++) {
        var marker = EMOJI_LEG_MARKERS[i][0];
        var at = name.indexOf(marker);
