           leg: anchor.leg || legFromAgent(row.agent),
           at: String(row.createdAt || ''),
           prompt: prompt,
           completion: completion,
           total: prompt + completion,
           cacheRead: +row.cachedTokens || 0,
           model: ''
       });
   });
