/**
 * gh-1108 — the keyed tokens projection: reporter rows → the map form the
 * tick's tokensMapOf/tokens normalize ('pr-N'/'issue-N' → rows sorted by
 * at). One row per RUN (the run's summed usage), shape = the printf row
 * contract {leg, at, prompt, completion, total, cacheRead, model}:
 * prompt=read, completion=write, total=in+out, cacheRead=cached. The logs
 * carry no model id yet — model stays '' (normTokenRow → null downstream,
 * honest unknown; pricing skips it). Rows without a resolvable anchor are
 * dropped (never a wrong key). Retention mirrors the fa producer:
 * drop rows older than cutoff (windowDays, default 14), keep the last
 * keepPerKey (default 40) rows per key sorted by at.
 */
function buildTokensMap(rows, opts) {
   opts = opts || {};
   var windowDays = opts.windowDays == null ? tokenUsage.DEFAULT_WINDOW_DAYS : +opts.windowDays;
   var keepPerKey = opts.keepPerKey == null ? tokenUsage.ROW_KEEP : +opts.keepPerKey;
   var now = opts.now ? new Date(opts.now) : new Date();
   var cutoff = tokenUsage.cutoffIso(now, windowDays);
   var byKey = {};
   (rows || []).forEach(function (row) {
       if (!row) return;
       var anchor = parseRunAnchor(row.title);
       if (!anchor.key) return;
       var n = +row.readTokens || 0, out = +row.writeTokens || 0;
       (byKey[anchor.key] = byKey[anchor.key] || []).push({
