                branch: branch,
                message: 'factory leg tokens — ' + rowCount + ' rows [skip ci]',
                json: JSON.stringify(map),
                sha: sha
            }) });
            ok = true;
        } catch (ePut) { ok = false; }
        result.attempts = attempt;
        if (ok) {
            result.status = 'published';
            return result;
        }
