        cutoff: tokenUsage.cutoffIso(
            opts.now ? new Date(opts.now) : new Date(),
            intOrDefault(opts.windowDays, tokenUsage.DEFAULT_WINDOW_DAYS)),
        keepPerKey: intOrDefault(opts.keepPerKey, tokenUsage.ROW_KEEP)
