function legFromAgent(agent) {
    var stem = String(agent || '');
    if (!stem) return '';
    if (stem.indexOf('rework') !== -1) return 'rework';
    if (stem.indexOf('review') !== -1) return 'review';
    if (stem.indexOf('develop') !== -1) return 'dev';
    return '';
