function tokensSkipReason(stats, opts, exec) {
    if (!stats.keys.length || !stats.rowCount) return 'no-rows';
    var repo = String(opts.repo || '');
    if (!repo || repo.indexOf('/') === -1) return 'no-repo';
    if (typeof exec !== 'function') return 'no-exec';
    return null;
