function tokensMapStats(map) {
    var keys = (map && typeof map === 'object' && !Array.isArray(map)) ?
        Object.keys(map) : [];
    var rowCount = 0;
    keys.forEach(function(k) {
        if (Array.isArray(map[k])) rowCount += map[k].length;
    });
    return { keys: keys, rowCount: rowCount };
